fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Assume 0 < n < list.len() and list is non-empty
    let len = list.len();
    // Pre-allocate a new Vec with the same capacity as the original
    let mut new_list = Vec::with_capacity(len);

    // First, append the subarray from n (inclusive) to the end
    new_list.extend_from_slice(&list[n..]);

    // Then, append the subarray from 0 (inclusive) up to n (exclusive)
    new_list.extend_from_slice(&list[..n]);

    new_list
}

